function solve({config,state,event}){
  let s=state||{head:null,records:{}};
  let old=s.records||{}, next={}, conflict=false;
  for(let k in old)next[k]=old[k];
  let seen={};
  for(let r of (event.records||[])){
    let x={p:r.parent,v:r.value};
    if(seen[r.id] && (seen[r.id].p!==x.p || seen[r.id].v!==x.v)) conflict=true;
    seen[r.id]=x;
    if(old[r.id] && (old[r.id].p!==x.p || old[r.id].v!==x.v)) conflict=true;
  }
  if(!conflict)for(let k in seen)next[k]=seen[k];
  let graph=conflict?old:next, remote=event.head;
  function walk(h){let a=[],miss={}; while(h!==null){a.push(h);if(!Object.prototype.hasOwnProperty.call(graph,h)){miss[h]=1;break}h=graph[h].p} if(h===null)a.push(null);return {a:a,m:miss,end:h};}
  let l=walk(s.head), r=walk(remote), miss={};
  for(let k in l.m)miss[k]=1;for(let k in r.m)miss[k]=1;
  let d,head=s.head;
  if(conflict)d='conflict';
  else if(s.head===remote)d='same';
  else if(l.a.indexOf(remote)>=0){d='ahead';}
  else if(r.a.indexOf(s.head)>=0){d='advance';head=remote;}
  else if(l.end===null&&r.end===null)d='fork';
  else d='unknown';
  let missing=Object.keys(miss).sort();
  return {state:{head:head,records:graph},output:{head:head,decision:d,missing:missing}};
}
